3|namespace App\Http\Controllers;
4|
5|use App\Enums\PaymentMethod;
6|use App\Models\Student;
7|use App\Services\AcademicReport;
8|use App\Services\BalanceReport;
9|use App\Services\ProfitAndLoss;
10|use Illuminate\Http\Request;
11|use Illuminate\View\View;
12|
13|/**
14| * گزارش‌ها.
15| *
16| * بازهٔ تاریخ همیشه شمسی از کاربر می‌آید و میلادی تبدیل و در گزارش اعمال
17| * می‌شود. کاربر تاریخ میلادی نمی‌شناسد؛ تبدیل در فرم گم شود، گزارش «بازهٔ
18| * اشتباه» می‌دهد و هیچ خطایی هم نشان نمی‌دهد.
19| */
20|class ReportController extends Controller
21|{
22|    public function __construct(
23|        private readonly BalanceReport $report,
24|        private readonly AcademicReport $academic,
25|        private readonly ProfitAndLoss $pnl,
26|    ) {}
27|
28|    public function balances(Request $request): View
29|    {
30|        $data = $request->validate([
31|            'from' => ['nullable', 'string'],
32|            'to' => ['nullable', 'string'],
33|            'only_debtors' => ['nullable'],
34|        ]);
35|
36|        $from = $this->toMiladi($data['from'] ?? null);
37|        $to = $this->toMiladi($data['to'] ?? null);
38|
39|        $students = Student::query()->orderBy('id')->get();
40|
41|        $rows = $this->report->build($students, $from, $to);
42|
43|        if ($request->boolean('only_debtors')) {
44|            $rows = $rows->filter(fn (array $row) => $row['outstanding'] > 0)->values();
45|        }
46|
47|        $byMethod = $this->report->collectedByMethod($from, $to);
48|
49|        return view('reports.balances', [
50|            'rows' => $rows,
51|            'totals' => $this->report->totals($rows),
52|            'from' => $data['from'] ?? null,
53|            'to' => $data['to'] ?? null,
54|            'onlyDebtors' => $request->boolean('only_debtors'),
55|            'byMethod' => $this->labelMethods($byMethod),
56|            'totalOutstanding' => $this->report->totalOutstanding($from, $to),
57|        ]);
58|    }
59|
60|    /** گزارش‌های آموزشی: حضور، نمرات، کم‌حضورها. */
61|    public function academic(Request $request): View
62|    {
63|        $data = $request->validate([
64|            'from' => ['nullable', 'string'],
65|            'to' => ['nullable', 'string'],
66|            'previous_from' => ['nullable', 'string'],
67|            'previous_to' => ['nullable', 'string'],
68|        ]);
69|
70|        $from = $this->toMiladi($data['from'] ?? null);
71|        $to = $this->toMiladi($data['to'] ?? null);
72|
73|        $previousFrom = $this->toMiladi($data['previous_from'] ?? null);
74|        $previousTo = $this->toMiladi($data['previous_to'] ?? null);
75|
76|        $students = Student::query()->orderBy('id')->get();
77|
78|        $academic = $this->academic;
79|
80|        $lowAttendance = $academic->lowAttendance($students, $from, $to);
81|
82|        // مقایسه با بازهٔ قبل فقط وقتی بازهٔ قبل داده شده باشد معنی دارد؛
83|        // بدون آن «رشد» نسبت به هیچ چیز محاسبه می‌شد
84|        $progress = null;
85|
86|        if ($previousFrom || $previousTo) {
87|            $progress = $students
88|                ->mapWithKeys(fn (Student $student) => [
89|                    $student->id => $academic->compare(
90|                        $student,
91|                        ['from' => $from, 'to' => $to],
92|                        ['from' => $previousFrom, 'to' => $previousTo],
93|                    ),
94|                ])
95|                ->filter(fn (array $delta) => $delta['attendance_delta'] !== null || $delta['score_delta'] !== null)
96|                ->map(fn (array $delta) => $delta + [
97|                    'attendance_trend' => $academic->trendLabel($delta['attendance_delta']),
98|                    'score_trend' => $academic->trendLabel($delta['score_delta']),
99|                ]);
100|        }
101|
102|        return view('reports.academic', [
103|            'rows' => $students->map(fn (Student $student) => [
104|                'student' => $student,
105|                'attendance' => $academic->attendanceFor($student, $from, $to),
106|                'average' => $academic->rawAverage($student, $from, $to),
107|                'grades' => $academic->gradesFor($student),
108|            ]),
109|            'lowAttendance' => $lowAttendance,
110|            'sessions' => $academic->sessionsIn($from, $to),
111|            'progress' => $progress,
112|            'from' => $data['from'] ?? null,
113|            'to' => $data['to'] ?? null,
114|            'previousFrom' => $data['previous_from'] ?? null,
115|            'previousTo' => $data['previous_to'] ?? null,
116|        ]);
117|    }
118|
119|    /** صورت سود و زیان. */
120|    public function profitAndLoss(Request $request): View
121|    {
122|        $data = $request->validate([
123|            'from' => ['nullable', 'string'],
124|            'to' => ['nullable', 'string'],
125|        ]);
126|
127|        $from = $this->toMiladi($data['from'] ?? null);
128|        $to = $this->toMiladi($data['to'] ?? null);
129|
130|        $pnl = $this->pnl;
131|
132|        return view('reports.profit-and-loss', [
133|            'income' => $pnl->income($from, $to),
134|            'expenses' => $pnl->expenses($from, $to),
135|            'profit' => $pnl->profit($from, $to),
136|            'byCategory' => $pnl->byCategory($from, $to),
137|            'fixedVsVariable' => $pnl->fixedVsVariable($from, $to),
138|            'monthly' => $pnl->monthly($from, $to),
139|            'from' => $data['from'] ?? null,
140|            'to' => $data['to'] ?? null,
141|        ]);
142|    }
143|
144|    /** تبدیل ورودی شمسی به میلادی، با خطای قابل فهم. */
145|    private function toMiladi(?string $value): ?string
146|    {
147|        if (blank($value)) {
148|            return null;
149|        }
150|
151|        try {
152|            return miladi_date($value);
153|        } catch (\InvalidArgumentException) {
154|            // تاریخ نامعتبر یعنی بازهٔ خالی، نه خطای مرگبار؛ ولی نباید بی‌صدا
155|            // به کل تاریخ‌ها تبدیل شود، پس مقدار خالی می‌ماند
156|            return null;
157|        }
158|    }
159|
160|    /**
161|     * @param  array<string, int>  $byMethod
162|     * @return array<string, int>
163|     */
164|    private function labelMethods(array $byMethod): array
165|    {
166|        $out = [];
167|
168|        foreach ($byMethod as $method => $total) {
169|            $label = PaymentMethod::tryFrom((string) $method)?->label() ?? 'نامشخص';
170|
171|            $out[$label] = ($out[$label] ?? 0) + (int) $total;
172|        }
173|
174|        return $out;
175|    }
