{"content": "1|<?php
2|
3|use Illuminate\Support\Carbon;
4|use Morilog\Jalali\Jalalian;
5|
6|/*
7||--------------------------------------------------------------------------
8|| نمایش تاریخ شمسی
9||--------------------------------------------------------------------------
10|| ذخیره‌سازی همیشه میلادی است (استاندارد Laravel و قابل مرتب‌سازی/فیلتر در
11|| پایگاه داده). تبدیل به شمسی فقط در لایه نمایش انجام می‌شود تا هیچ‌جا تاریخ
12|| به رشته شمسی ذخیره نشود و بازه‌های تاریخی (whereBetween) درست کار کند.
13|*/
14|
15|if (! function_exists('jalali_date')) {
16|    /**
17|     * نمایش شمسی هر مقدار تاریخ‌پذیر.
18|     *
19|     * @param  string|int|null  $date  رشته میلادی، timestamp یا شیء تاریخ
20|     */
21|    function jalali_date(string|int|DateTimeInterface|null $date, string $format = 'Y/m/d'): ?string
22|    {
23|        if (blank($date)) {
24|            return null;
25|        }
26|
27|        if ($date instanceof DateTimeInterface) {
28|            return Jalalian::fromDateTime($date)->format($format);
29|        }
30|
31|        if (is_int($date)) {
32|            // createFromTimestamp, not '@'.$date: the '@' form is parsed as UTC and
33|            // shifts the shamsi day by one depending on the server timezone.
34|            return Jalalian::fromCarbon(Carbon::createFromTimestamp($date, date_default_timezone_get()))->format($format);
35|        }
36|
37|        return Jalalian::fromDateTime($date)->format($format);
38|    }
39|}
40|
41|if (! function_exists('jalali_date_time')) {
42|    /**
43|     * نمایش شمسی تاریخ و ساعت — برای لاگ‌ها و زمان ثبت رخداد.
44|     */
45|    function jalali_date_time(string|int|DateTimeInterface|null $date, string $format = 'Y/m/d H:i'): ?string
46|    {
47|        return jalali_date($date, $format);
48|    }
49|}
50|
51|if (! function_exists('miladi_date')) {
52|    /**
53|     * تبدیل تاریخ شمسی ورودی کاربر به میلادی قابل ذخیره.
54|     * ورودی کاربر هم ارقام فارسی و هم ارقام لاتین و هم جداکننده‌های متنوع را می‌پذیرد.
55|     *
56|     * @throws InvalidArgumentException اگر تاریخ شمسی معتبر نباشد
57|     */
58|    function miladi_date(?string $date, string $format = 'Y-m-d'): ?string
59|    {
60|        if (blank($date)) {
61|            return null;
62|        }
63|
64|        $normalized = normalize_jalali_input($date);
65|
66|        if (! preg_match('#^(\d{4})[\/-](\d{1,2})[\/-](\d{1,2})$#', $normalized, $m)) {
67|            throw new InvalidArgumentException("قالب تاریخ شمسی نامعتبر است: {$date} (باید به شکل ۱۴۰۳/۰۵/۱۲ باشد)");
68|        }
69|
70|        [, $year, $month, $day] = $m;
71|
72|        $year = (int) $year;
73|        $month = (int) $month;
74|        $day = (int) $day;
75|
76|        $maxDay = jalali_month_days($year, $month);
77|
78|        if ($day > $maxDay) {
79|            throw new InvalidArgumentException(
80|                "روز {$day} در ماه {$month} سال {$year} وجود ندارد (بیشترین روز: {$maxDay})"
81|            );
82|        }
83|
84|        return (new Jalalian($year, $month, $day))->toCarbon()->format($format);
85|    }
86|}
87|
88|/*
89||--------------------------------------------------------------------------
90|| ارقام فارسی
91||--------------------------------------------------------------------------
92|| کاربر ایرانی «۱۲۳۴» یا «۱۲٬۵۰۰» تایپ می‌کند. ذخیره باید همیشه لاتین باشد،
93|| نمایش همیشه فارسی. تبدیل باید پیش از اعتبارسنجی انجام شود تا قاعده روی
94|| مقدار درست اجرا شود نه روی ورودی خام.
95|*/
96|
97|if (! function_exists('to_english_digits')) {
98|    /**
99|     * اربانی/فارسی/عربی → لاتین. جداکننده‌های هزارگان و ممیز حفظ می‌شوند.
100|     */
101|    function to_english_digits(string $value): string
102|    {
103|        return strtr($value, [
104|            '۰' => '0', '۱' => '1', '۲' => '2', '۳' => '3', '۴' => '4',
105|            '۵' => '5', '۶' => '6', '۷' => '7', '۸' => '8', '۹' => '9',
106|            '٠' => '0', '١' => '1', '٢' => '2', '٣' => '3', '٤' => '4',
107|            '٥' => '5', '٦' => '6', '٧' => '7', '٨' => '8', '٩' => '9',
108|        ]);
109|    }
110|}
111|
112|if (! function_exists('to_persian_digits')) {
113|    /**
114|     * لاتین → فارسی برای نمایش. ارقام نمایش‌داده‌شده هیچ‌وقت در دیتابیس یا
115|     * محاسبات شرکت نمی‌کنند؛ فقط در لایه view صدا زده می‌شود.
116|     */
117|    function to_persian_digits(string|int|float|null $value): string
118|    {
119|        if ($value === null || $value === '') {
120|            return '';
121|        }
122|
123|        return strtr((string) $value, [
124|            '0' => '۰', '1' => '۱', '2' => '۲', '3' => '۳', '4' => '۴',
125|            '5' => '۵', '6' => '۶', '7' => '۷', '8' => '۸', '9' => '۹',
126|
127|            // جداکننده‌ها هم فارسی می‌شوند. «۲,۰۰۰,۰۰۰» با کامای لاتین وسطش
128|            // نیمه‌فارسی به نظر می‌رسد؛ و در RTL جای ممیز هم غلط دیده می‌شود
129|            ',' => '٬',
130|            '.' => '٫',
131|        ]);
132|    }
133|}
134|
135|if (! function_exists('normalize_jalali_input')) {
136|    /**
137|     * پاکسازی ورودی تاریخ شمسی: ارقام فارسی → لاتین، حذف فاصله و نیم‌فاصله،
138|     * تبدیل خط تیره/نقطه به اسلش. قالب‌های رایج کاربر را یکسان می‌کند.
139|     */
140|    function normalize_jalali_input(string $value): string
141|    {
142|        $value = to_english_digits($value);
143|
144|        // نیم‌فاصله و بی‌عرضه حذف می‌شوند (تایپ با کیبورد فارسی)، اما جداکننده‌های
145|        // تاریخ به اسلش تبدیل می‌شوند — حذفشان «۱۴۰۳ ۰۵ ۱۲» را به «۱۴۰۳۰۵۱۲»
146|        // تبدیل می‌کند که دیگر قابل تفسیر نیست.
147|        $value = strtr($value, [
148|            "\u{200C}" => '', "\u{200F}" => '', "\u{00A0}" => '',
149|            '-' => '/', '.' => '/', '\\' => '/', ' ' => '/',
150|        ]);
151|
152|        return trim(preg_replace('#/+#', '/', $value), '/');
153|    }
154|}
155|
156|if (! function_exists('parse_number')) {
157|    /**
158|     * تبدیل ورودی عددی کاربر به عدد.
159|     * «۱۲٬۵۰۰»، «12,500»، «۱۲۵۰۰» همه به 12500 تبدیل می‌شوند.
160|     * رشته خالی یا فقط نشانه‌های نامعتبر → null (نه صفر؛ صفر یعنی مقدار واقعی صفر).
161|     */
162|    function parse_number(mixed $value): ?float
163|    {
164|        if ($value === null || is_bool($value)) {
165|            return null;
166|        }
167|
168|        if (is_int($value) || is_float($value)) {
169|            return (float) $value;
170|        }
171|
172|        $normalized = to_english_digits((string) $value);
173|        // حذف جداکننده هزارگان فارسی/عربی، کاما و فاصله؛ ممیز نقطه و اسلش حفظ می‌شود
174|        $normalized = strtr($normalized, ['٬' => '', '،' => '', ',' => '', ' ' => '']);
175|        $normalized = rtrim($normalized, '-');
176|
177|        if ($normalized === '' || ! is_numeric($normalized)) {
178|            return null;
179|        }
180|
181|        return (float) $normalized;
182|    }
183|}
184|
185|if (! function_exists('parse_integer')) {
186|    /**
187|     * مشابه parse_number ولی خروجی صحیح — برای کد ملی، کد پستی، شماره موبایل.
188|     */
189|    function parse_integer(mixed $value): ?int
190|    {
191|        $number = parse_number($value);
192|
193|        return $number === null ? null : (int) round($number);
194|    }
195|}
196|
197|if (! function_exists('jalali_month_name')) {
198|    /**
199|     * نام فارسی ماه شمسی — برای عنوان تقویم و فیلترهای گزارش.
200|     */
201|    function jalali_month_name(int $month): string
202|    {
203|        return [
204|            1 => 'فروردین', 2 => 'اردیبهشت', 3 => 'خرداد', 4 => 'تیر',
205|            5 => 'مرداد', 6 => 'شهریور', 7 => 'مهر', 8 => 'آبان',
206|            9 => 'آذر', 10 => 'دی', 11 => 'بهمن', 12 => 'اسفند',
207|        ][$month] ?? '';
208|    }
209|}
210|
